beforeExample:
package test;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class MyTest {
    public boolean someMethod() { return false; }

    @Test
    public void testSomething() {
        boolean condition = false;
        assertEquals(false, condition);
        assertEquals(false, someMethod());
    }
}

afterExample:
package test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import org.junit.Test;

public class MyTest {
    public boolean someMethod() { return false; }

    @Test
    public void testSomething() {
        boolean condition = false;
        assertFalse(condition);
        assertFalse(someMethod());
    }
}

negativeExample:
package test;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class MyTest {
    public boolean someMethod() { return false; }

    @Test
    public void testSomethingElse() {
        assertEquals("message", false, false); // Has 3 args
        assertEquals("message", someMethod(), false); // false is not the first arg (2nd argument)
        assertEquals(1, 1); // Not assertEquals(false, ...)
        assertEquals(true, someMethod()); // different literal
    }
}
